return [
  { json: { project_id: '691331356a3b9a68428ab3.43540470', project_name: 'Chat AI - frontend' } },
  { json: { project_id: '225008626a33e62b328c63.04676982', project_name: 'Chat AI (emails)' } }
];

const meta = $('Projects').all();
const rows = $input.all();
function screenTag(title) {
  let t = String(title || '');
  t = t.replace(/^[DM]\s*-\s*/, '');
  t = t.replace(/^Email\s*-\s*/i, 'email_');
  t = t.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  if (t.length > 60) { t = t.slice(0, 60).replace(/_+$/, ''); }
  return 'screen_' + t;
}
function isFigma(s) {
  const tags = s.screenshot_tags || s.tags || [];
  if (tags.indexOf('figma') !== -1) { return true; }
  return /^[DM]\s*-\s/.test(String(s.title || ''));
}
const out = [];
const skipped = [];
for (let i = 0; i < rows.length; i++) {
  const pi = rows[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const m = (meta[idx] || meta[i] || {}).json || {};
  const r = rows[i].json || {};
  if (r.statusCode !== 200) { continue; }
  const shots = (r.body && r.body.screenshots) ? r.body.screenshots : [];
  const byTag = {};
  for (const s of shots) {
    if (!isFigma(s)) { skipped.push(m.project_name + ' / ' + s.title); continue; }
    const tag = screenTag(s.title);
    if (!byTag[tag]) { byTag[tag] = {}; }
    for (const kid of (s.key_ids || [])) { byTag[tag][String(kid)] = true; }
  }
  for (const tag of Object.keys(byTag)) {
    const keys = [];
    for (const id of Object.keys(byTag[tag])) { keys.push({ key_id: Number(id), tags: [tag, 'has_screenshot'], merge_tags: true }); }
    if (!keys.length) { continue; }
    out.push({ json: { project_id: m.project_id, project_name: m.project_name, tag: tag, key_count: keys.length, skipped_titles: skipped, payload: { keys: keys } } });
  }
}
return out;

const meta = $('Build Tag Requests').all();
const rows = $input.all();
const ok = [];
const bad = [];
let keysTagged = 0;
for (let i = 0; i < rows.length; i++) {
  const pi = rows[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const m = (meta[idx] || meta[i] || {}).json || {};
  const r = rows[i].json || {};
  if (r.statusCode === 200) { ok.push(m.project_name + ' / ' + m.tag + ' (' + m.key_count + ')'); keysTagged += m.key_count; }
  else { bad.push(m.project_name + ' / ' + m.tag + ' -> ' + r.statusCode + ' ' + JSON.stringify(r.body).slice(0, 200)); }
}
return [{ json: { tag_groups_ok: ok.length, tag_groups_failed: bad.length, key_tag_writes: keysTagged, failures: bad, groups: ok } }];
